## Monte Carlo

ld_montecarlo <- function(object, p = 0.5, cf = 1:2, level = 0.95, nboot = 1000,
                          interval_type = c("eti","hdi","bca","all")) {
  original_d_hat <- dose.p(object, p = p, cf = cf)
  varcovar_mat <- stats::vcov(object)[cf,cf]
  mean_vec <- coef(object)[cf]

  beta_sim <- rmvnorm(n = nboot, mean = mean_vec, sigma = varcovar_mat)

  linkfun <- object$family$linkfun
  p_const <- linkfun(p)

  d_hat <- matrix(NA, ncol = length(p), nrow = nboot)

  for(i in 1:length(p)) {
    d_hat[,i] <- (p_const[i] - beta_sim[,1]) / beta_sim[,2]
  }

  res <- switch(interval_type,
                "eti" = cbind(lower = apply(d_hat, 2, quantile, (1-level)/2),
                              estimate = original_d_hat,
                              upper = apply(d_hat, 2, quantile, (1+level)/2)),
                "hdi" = {
                  if(length(level) == 1) {
                    hdi_interval <- apply(d_hat, 2, hdi, level)
                    return(
                      cbind(lower = hdi_interval[1,],
                            estimate = original_d_hat,
                            upper = hdi_interval[2,])
                    )
                  } else {
                    hdi_interval <- list()
                    for(l in 1:length(level)) {
                      hdi_interval[[l]] <- as.numeric(apply(d_hat, 2, hdi, level[l]))
                    }
                    ret <- do.call(rbind, hdi_interval)
                    ret <- cbind(ret, rep(original_d_hat, length(level)))
                    ret <- ret[,c(1,3,2)]
                    colnames(ret) <- c("lower","estimate","upper")
                    return(ret)}
                },
                "bca" = {
                  bca_interval <- get_bca(object = object, p = p, cf = cf,
                                          d_hat = d_hat, original_d_hat = original_d_hat,
                                          nboot = nboot, level = level)
                  bca_interval <- matrix(bca_interval, ncol = 2, nrow = length(level), byrow = FALSE)
                  return(cbind(lower = bca_interval[,1],
                               estimate = original_d_hat,
                               upper = bca_interval[,2]))
                },
                "all" = {
                  perc <- cbind(lower = apply(d_hat, 2, quantile, (1-level)/2),
                                estimate = original_d_hat,
                                upper = apply(d_hat, 2, quantile, (1+level)/2))
                  if(length(level) == 1) {
                    hdi_interval <- apply(d_hat, 2, hdi, level)
                    hdi_int <- cbind(lower = hdi_interval[1,],
                                     estimate = original_d_hat,
                                     upper = hdi_interval[2,])
                  } else {
                    hdi_interval <- list()
                    for(l in 1:length(level)) {
                      hdi_interval[[l]] <- as.numeric(apply(d_hat, 2, hdi, level[l]))
                    }
                    ret <- do.call(rbind, hdi_interval)
                    ret <- cbind(ret, rep(original_d_hat, length(level)))
                    ret <- ret[,c(1,3,2)]
                    colnames(ret) <- c("lower","estimate","upper")
                    hdi_int <- ret
                  }
                  bca_interval <- get_bca(object = object, p = p, cf = cf,
                                          d_hat = d_hat, original_d_hat = original_d_hat,
                                          nboot = nboot, level = level)
                  bca_interval <- matrix(bca_interval, ncol = 2, nrow = length(level), byrow = FALSE)
                  bca_int <- cbind(lower = bca_interval[,1],
                                   estimate = original_d_hat,
                                   upper = bca_interval[,2])
                  return(list("eti" = perc, "hdi" = hdi_int, "bca" = bca_int))
                })
  print(res)
  return(res)
}

get_bca <- function(object, p, cf, d_hat, original_d_hat, nboot, level) {
  alpha <- c((1-level)/2, level + (1-level)/2)
  n <- nrow(object$data)
  u <- rep(0, n)
  for(i in 1:n) {

  new_fit <- glm(
    formula = formula(object),
    family = object$family,
    data = object$data[-i,]
  )

  u[i] <- as.numeric(dose.p(new_fit, p = p, cf = cf))
  }

  prop <- sum(d_hat < original_d_hat) / nboot
    prop <- max(
    min(prop, 1 - 1/(2*nboot)),
    1/(2*nboot)
  )

  z0 <- stats::qnorm(prop)
  uu <- mean(u) - u
  acc <- sum(uu * uu * uu)/(6 * (sum(uu * uu))^1.5)
  zalpha <- stats::qnorm(alpha)
  tt <- stats::pnorm(z0 + (z0 + zalpha)/(1 - acc * (z0 + zalpha)))
  confpoints <- as.numeric(stats::quantile(x = d_hat, probs = tt, type = 1))
  return(confpoints)
}

##### Fonction pour extraction des valeurs du modèles (L50, IC, b0, b1, b2, b3)

maturite_extract_resultats_modele <- function(mod, id = NULL) {

  if (is.null(id)) {
    stop("id doit être fourni.")
  }

  type_modele <- sub("_.*$", "", id)
  is_separated <- grepl("^[MF]_", id)
  variable <- c("ltm", "age")

    # Coefficients
  coef_mod <- stats::coef(mod)
  coef_names <- names(coef_mod)

  b0 <- if ("(Intercept)" %in% coef_names) {
    unname(coef_mod["(Intercept)"])
  } else {
    NA_real_
  }

  b1 <- NA_real_
  b2 <- NA_real_
  b3 <- NA_real_

  if (type_modele == "COM") {

    idx_b1 <- grep(paste0("^(", paste(variable, collapse = "|"), "):sexeF$"),
      coef_names)      
    if (length(idx_b1) > 0) {
      b1 <- unname(coef_mod[idx_b1[1]])
    }

    idx_b2 <- grep(
      paste0("^(", paste(variable, collapse = "|"), "):sexeM$"),
      coef_names)

    if (length(idx_b2) > 0) {
      b2 <- unname(coef_mod[idx_b2[1]])
    }  

  } else {

    idx_b1 <- which(coef_names %in% c("ltm", "age"))

  if (length(idx_b1) > 0) {
    b1 <- unname(coef_mod[idx_b1[1]])
  }

  idx_sexe <- grep("^sexe", coef_names)
  if (length(idx_sexe) > 0) {
    b2 <- unname(coef_mod[idx_sexe[1]])
  }

  idx_inter <- grep(":sexeM$", coef_names)
  if (length(idx_inter) > 0) {
    b3 <- unname(coef_mod[idx_inter[1]])
  }
  }

  # Point50 et IC95

  point50 <- NA_real_

  point50_F <- NA_real_
  point50_M <- NA_real_

  point50_IC95_inf <- NA_real_
  point50_IC95_sup <- NA_real_

  conv <- isTRUE(mod$converged)

  if (
    conv &&
    is.finite(b0) &&
    is.finite(b1) &&
    b1 != 0
  ) {

    # ------------------------------------------------------------------------
    # Modèles séparés et TLO
    # ------------------------------------------------------------------------

    if (is_separated || type_modele == "TLO") {

      ci_L <- tryCatch(
        confint_L(
          object = mod,
          method = "delta", # mieux pour A50 
          interval_type = "bca"
        ),
        error = function(e) {
          print(e)
          NULL
       }
    )

      if (
        !is.null(ci_L) &&
        is.matrix(ci_L) &&
        nrow(ci_L) >= 1 &&
        all(c("estimate", "lower", "upper") %in% colnames(ci_L))
      ) {

        point50 <- as.numeric(
          ci_L[1, "estimate"]
        )

        point50_IC95_inf <- as.numeric(
          ci_L[1, "lower"]
        )

        point50_IC95_sup <- as.numeric(
          ci_L[1, "upper"]
        )
      }

    } else {

      # ----------------------------------------------------------------------
      # ADD / COM / INT
      # ----------------------------------------------------------------------

      lien <- as.character(mod$family$link)

      kappa <- if (lien == "cloglog") {
        0.3665129
      } else {
        0
      }

      if (type_modele == "ADD") {

        point50_F <- (-b0 - kappa) / b1

        point50_M <- (-b0 - b2 - kappa) / b1

      } else if (type_modele == "COM") {

        point50_F <- (-b0 - kappa) / b1

        point50_M <- (-b0 - kappa) / b2

      } else if (type_modele == "INT") {

        point50_F <- (-b0 - kappa) / b1

        point50_M <- (-b0 - b2 - kappa) / (b1 + b3)
      }
    }
  }

  return(
    list(
      b0 = b0,
      b1 = b1,
      b2 = b2,
      b3 = b3,
      point50 = point50,
      point50_F = point50_F,
      point50_M = point50_M,
      point50_IC95_inf = point50_IC95_inf,
      point50_IC95_sup = point50_IC95_sup
    )
  )
}

####################################################
##### Fonction pour ajustement du modèle (o.r.test, p_link, AICc et delta_AICc)

maturite_evaluer_ajustement <- function(mod) {

  conv <- isTRUE(mod$converged)

  p_fit <- tryCatch(
    o.r.test(mod),
    error = function(e) NA_real_
  )

  p_link <- tryCatch(
    maturite_test_lien(mod),
    error = function(e) NA_real_
  )

  aicc <- tryCatch(
    MuMIn::AICc(mod),
    error = function(e) NA_real_
  )

  ajust <- conv &&
    (is.na(p_fit) || p_fit > 0.05) &&
    (is.na(p_link) || p_link > 0.05)

  list(
    convergence = conv,
    pearson_x2_pval = p_fit,
    goodness_of_link_pval = p_link,
    ajust = ajust,
    aicc = aicc
  )
}

#' Ajuste un modèle de maturité (L50 ou A50)
#'
#' Cette fonction ajuste un modèle de maturité en fonction du type de modèle (`TLO`, `ADD`, `COM`, `INT`) 
#' et du lien (`logit`, `probit`, `cloglog`) spécifiés. Elle retourne un tableau de résultats, 
#' un graphique de l'ogive de reproduction, un commentaire sur l'ajustement, et les prédictions associées.
#'
#' @param data Jeu de données contenant les colonnes `maturite`, `sexe`, et `ltm` ou `age`
#' @param variable Variable quantitative à utiliser : `"ltm"` (par défaut) ou `"age"`
#' @param modele Type de modèle : `"TLO"`, `"ADD"`, `"COM"` ou `"INT"`
#' @param lien Lien à utiliser dans le glm : `"probit"` (par défaut), `"logit"`, `"cloglog"`
#'
#' @return Une liste avec :
#' \describe{
#'   \item{success}{Indique si le modèle a pu être ajusté}
#'   \item{message}{Message explicatif si l'analyse n'est pas disponible}
#'   \item{graphique}{Ogive de reproduction}
#'   \item{donnees_ogive}{Données prédictives}
#' }
#'
#' @export
#' @importFrom stats glm binomial predict anova coef update plogis pnorm
#' @importFrom glue glue
#' @importFrom dplyr bind_rows filter mutate pull
#' @importFrom ggplot2 ggplot aes geom_line geom_ribbon geom_point labs annotate theme
#' @importFrom FSA Summarize

maturite_generate_modele <- function(data,
                                     variable = c("ltm", "age"),
                                     modele = c("TLO", "ADD", "COM", "INT"),
                                     lien = c("probit", "logit", "cloglog"),
                                     sexe = NULL,
                                     modele_glm = NULL) {

  # Validation des arguments optionnels ----
  if (is.null(modele) || is.null(lien) || is.null(variable)) {
    return(list(
      success = FALSE,
      message = "Modèle non disponible pour ce groupe.",
      commentaire = NULL,
      table_resultats = NULL,
      table_resultats_flextable = NULL,
      graphique = NULL,
      donnees_ogive = NULL
    ))
  }

  variable <- match.arg(variable)
  modele <- match.arg(modele)
  lien <- match.arg(lien)

  if (!all(c(variable, "maturite", "sexe", "sp") %in% names(data))) {
    stop(glue("❌ Le jeu de données doit contenir les colonnes `{variable}`, `sp`, `maturite` et `sexe`."))
  }

  espece <- unique(stats::na.omit(as.character(data$sp)))
  if (length(espece) != 1) {
    stop("Les données doivent contenir une seule espèce (sp).")
  }

  info_espece <- get_info_pen(espece)

  couleur_default <- info_espece$couleur_default
  group_colors    <- info_espece$group_colors

  # Validation minimale des cas limites ----
  validation_res <- maturite_validate_data(
    specimen_data = data,
    variable = variable)

  if (!isTRUE(validation_res$success)) {
    return(list(
      success = FALSE,
      table_resultats = NULL,
      table_resultats_flextable = NULL,
      commentaire = NULL,
      message = validation_res$message,
      graphique = NULL,
      donnees_ogive = NULL
    ))
  }

  donnees_modeles <- maturite_prepare(data, variable = variable)

  if (!is.null(sexe)) {

    donnees_modeles <- donnees_modeles |>
      dplyr::filter(.data$sexe == .env$sexe)

  }

  # Ajustement du modèle ----------------------------------------------------

  if (is.null(modele_glm)) {

    # Refit seulement lorsque le modèle glm n'est pas fourni.
    # Normalement les modules L50/A50 transmettent déjà modele_glm.

        modele_glm <- glm(
        formula = maturite_get_formule(
          modele = modele,
          variable = variable
        ),
        family = binomial(link = lien),
        data = donnees_modeles
      )
  }  

  # Application des fonctions d'ajustement et d'évaluation du modèle

  stats_mod <- maturite_extract_resultats_modele(
    mod = modele_glm,
    id = paste(modele, lien, sep = "_")
  )

  if (modele == "TLO") {

    point50 <- stats_mod$point50
    point50_inf <- stats_mod$point50_IC95_inf
    point50_sup <- stats_mod$point50_IC95_sup

  } else {

    point50 <- list(
      fem = stats_mod$point50_F,
      male = stats_mod$point50_M
    )

    point50_inf <- NA_real_

    point50_sup <- NA_real_
  }

  # Calcul des prédictions pour la courbe ---------------------------------------
  if (modele == "TLO") {
    x_min <- min(donnees_modeles[[variable]], na.rm = TRUE)
    x_max <- max(donnees_modeles[[variable]], na.rm = TRUE)
    donnees_prediction <- data.frame(temp = seq(from = x_min, to = x_max, by = 1))
    names(donnees_prediction) <- variable
  } else {
    form <- stats::as.formula(glue("{variable} ~ sexe"))
    var_minmax <- Summarize(form, data = donnees_modeles)
    donnees_prediction <- bind_rows(
      data.frame(sexe = "F", temp = seq(from = var_minmax$min[var_minmax$sexe == "F"], to = var_minmax$max[var_minmax$sexe == "F"], by = 1)),
      data.frame(sexe = "M", temp = seq(from = var_minmax$min[var_minmax$sexe == "M"], to = var_minmax$max[var_minmax$sexe == "M"], by = 1))
    )
    names(donnees_prediction)[names(donnees_prediction) == "temp"] <- variable
  }

  prediction_model <- predict(modele_glm, donnees_prediction, full = TRUE, type = "link", se.fit = TRUE)

  donnees_ogive <- donnees_prediction |>
    mutate(
      maturite = switch(lien,
                        probit = pnorm(prediction_model$fit),
                        logit = plogis(prediction_model$fit),
                        cloglog = 1 - exp(-exp(prediction_model$fit))),
      lim_inf = switch(lien,
                       probit = pnorm(prediction_model$fit - 1.96 * prediction_model$se.fit),
                       logit = plogis(prediction_model$fit - 1.96 * prediction_model$se.fit),
                       cloglog = 1 - exp(-exp(prediction_model$fit - 1.96 * prediction_model$se.fit))),
      lim_sup = switch(lien,
                       probit = pnorm(prediction_model$fit + 1.96 * prediction_model$se.fit),
                       logit = plogis(prediction_model$fit + 1.96 * prediction_model$se.fit),
                       cloglog = 1 - exp(-exp(prediction_model$fit + 1.96 * prediction_model$se.fit)))
    )


  # Graphique -------------------------------------------------------------------

  couleur_ogive <- couleur_default

  if (!is.null(sexe)) {

    couleur_ogive <- switch(
      sexe,
      "F" = unname(group_colors$sexe["F"]),
      "M" = unname(group_colors$sexe["M"]),
      couleur_default
    )

  }

  color_by_sex <- "sexe" %in% names(donnees_ogive)

  titre_graphique <- "Ogive de reproduction"

  if (identical(sexe, "F")) {
    titre_graphique <- "Ogive de reproduction – Femelles"
  }

  if (identical(sexe, "M")) {
    titre_graphique <- "Ogive de reproduction – Mâles"
  }


  graphique <- ggplot(data = donnees_ogive, aes(x = .data[[variable]], y = .data$maturite)) +

    { if (color_by_sex) {
    geom_ribbon(aes(ymin = .data$lim_inf, ymax = .data$lim_sup, group = .data$sexe), alpha = 0.4, fill = "grey60")

      } else  {
        geom_ribbon(aes(ymin = .data$lim_inf, ymax = .data$lim_sup), alpha = 0.4, fill = "grey75")

      }
    } +
    { if (color_by_sex) {
      geom_line(aes(color = .data$sexe))
    } else {
        geom_line(color = couleur_ogive) }
    } +

    { 
      if (color_by_sex) scale_color_manual(
        values = group_colors$sexe,
        labels = group_labels$sexe
      ) else NULL 
    } +

    labs(
      x = ifelse(variable == "ltm",
                 "Longueur maximale (mm)",
                 "Âge"),
      y = "Proportion reproducteurs actifs",
      title = titre_graphique,
      color = "Sexe"
    ) +

    theme_aquapop()

  if (modele == "TLO") {
    graphique <- graphique +
      annotate("segment", x = point50, xend = point50, y = 0, yend = 0.5, color = couleur_ogive, lty = 2) +
      annotate("segment", x = x_min, xend = point50, y = 0.5, yend = 0.5, color = couleur_ogive, lty = 2)
  }

  if (modele %in% c("COM", "ADD", "INT")) {
    if (modele == "COM") {
      vmin_m <- min(donnees_modeles |> filter(.data$sexe == "M") |> pull(.data[[variable]]))
      vmin_f <- min(donnees_modeles |> filter(.data$sexe == "F") |> pull(.data[[variable]]))
    } else {
      form <- stats::as.formula(glue("{variable} ~ sexe"))
      var_minmax <- Summarize(form, data = donnees_modeles)
      vmin_m <- var_minmax |> filter(.data$sexe == "M") |> pull(.data$min)
      vmin_f <- var_minmax |> filter(.data$sexe == "F") |> pull(.data$min)
    }

    graphique <- graphique +
      annotate("segment", x = point50$male, xend = point50$male, y = 0, yend = 0.5, color = group_colors$sexe["M"], lty = 2) +
      annotate("segment", x = vmin_m, xend = point50$male, y = 0.5, yend = 0.5, color = group_colors$sexe["M"], lty = 2) +
      annotate("segment", x = point50$fem, xend = point50$fem, y = 0, yend = 0.5, color = group_colors$sexe["F"], lty = 2) +
      annotate("segment", x = vmin_f, xend = point50$fem, y = 0.5, yend = 0.5, color = group_colors$sexe["F"], lty = 2)

  }

  graphique <- graphique +
    {
      if (color_by_sex) {

        geom_point(
          data = donnees_modeles,
          mapping = aes(
            x = .data[[variable]],
            y = as.numeric(.data$maturite) - 1,
            color = .data$sexe),
          alpha = 0.5)

      } else {

        geom_point(
          data = donnees_modeles,
          mapping = aes(
            x = .data[[variable]],
            y = as.numeric(.data$maturite) - 1),
          color = couleur_ogive,
          alpha = 0.5)
      }
    }

  graphique <- graphique +
    labs(
      subtitle = glue(
        "Modèle : {modele} • Lien : {lien}"
      )
    )

  return(list(
    success = TRUE,
    message = NULL,
    graphique = graphique,
    donnees_ogive = donnees_ogive
  ))
}

#' Valider et préparer les données de maturité
#'
#' Fonction interne utilisée par les fonctions de modélisation de la maturité
#' pour gérer proprement les cas limites avant l'ajustement des modèles.
#'
#' Elle vérifie :
#' \itemize{
#'   \item la présence des colonnes requises ;
#'   \item si le jeu de données brut est vide ;
#'   \item si des données sont disponibles pour la variable demandée (`ltm` ou `age`) ;
#'   \item si des données exploitables demeurent après nettoyage ;
#'   \item si les deux états de maturité (`N` et `O`) sont présents.
#' }
#'
#' Contrairement aux versions précédentes, aucun seuil minimal d'effectif (`n`)
#' n'est imposé. Si les données sont présentes mais insuffisantes pour ajuster
#' correctement un modèle, cela sera détecté plus tard lors de l'ajustement
#' (ex. : non-convergence des modèles).
#'
#' @param specimen_data Un `data.frame` contenant les données de spécimens.
#' @param variable Chaîne indiquant la variable quantitative à utiliser :
#'   `"ltm"` ou `"age"`.
#'
#' @return Une liste contenant :
#' \describe{
#'   \item{success}{Booléen indiquant si les données sont exploitables}
#'   \item{data}{`data.frame` préparé pour la modélisation, ou `NULL`}
#'   \item{message}{Message explicatif si les données sont non exploitables}
#' }
#'
#' @details
#' Cette fonction distingue explicitement le cas où aucune donnée n'est disponible
#' pour la variable demandée (`ltm` ou `age`). Dans ce cas, un message spécifique
#' est retourné. Dans tous les autres cas, les données sont transmises aux fonctions
#' d'ajustement, même si elles sont limitées.
#'
#' @keywords internal
#'
#' @examples
#' \dontrun{
#' data_exemple <- data.frame(
#'   maturite = c("N", "O", "IND", "O"),
#'   sexe = c("F", "M", "F", "IND"),
#'   ltm = c(250, 320, 280, 300),
#'   age = c(2, 4, 3, 5)
#' )
#'
#' maturite_validate_data(data_exemple, variable = "ltm")
#' }
#'
#' @importFrom checkmate assert_choice assert_data_frame
#' @importFrom dplyr filter mutate
#' @importFrom glue glue
#' @importFrom rlang .data
maturite_validate_data <- function(specimen_data,
                                   variable = c("ltm", "age")) {
  variable <- match.arg(variable)

  # Validation des intrants ----
  assert_data_frame(specimen_data, any.missing = TRUE)
  assert_choice(variable, c("ltm", "age"))

  colonnes_requises <- c("maturite", "sexe", variable)
  colonnes_manquantes <- setdiff(colonnes_requises, names(specimen_data))

  if (length(colonnes_manquantes) > 0) {
    stop(
      glue(
        "Le jeu de données doit contenir les colonnes : {paste(colonnes_requises, collapse = ', ')}."
      )
    )
  }

  # Cas sans ligne ----
  if (nrow(specimen_data) == 0) {
    return(list(
      success = FALSE,
      data = NULL,
      message = paste(
        "Aucun spécimen valide disponible pour modéliser la maturité",
        "en fonction de",
        ifelse(variable == "ltm", "la longueur.", "l'âge.")
      )
    ))
  }

  # Cas particulier : aucune donnée disponible pour la variable demandée ----
  if (all(is.na(specimen_data[[variable]]))) {
    return(list(
      success = FALSE,
      data = NULL,
      message = if (variable == "age") {
        "Il n'y a pas d'âge disponible dans ce jeu de données, ce qui empêche la modélisation de l'âge à maturité."
      } else {
        "Il n'y a pas de longueur disponible dans ce jeu de données, ce qui empêche la modélisation de la longueur à maturité."
      }
    ))
  }

  # Préparation des données ----
  data_preparee <- specimen_data |>
    filter(
      .data$maturite != "IND",
      .data$sexe != "IND",
      !is.na(.data[[variable]])
    ) |>
    mutate(
      maturite = factor(.data$maturite, levels = c("N", "O"), ordered = TRUE),
      sexe = factor(.data$sexe, levels = c("F", "M"))
    ) |>
    mutate(
      age = age + if_else(sp == "SAVI", 1, 0)
    ) |>
    droplevels()

  # Cas sans donnée exploitable après nettoyage ----
  if (nrow(data_preparee) == 0) {
    return(list(
      success = FALSE,
      data = NULL,
      message = paste(
        "Aucune donnée exploitable n'est disponible après le nettoyage des",
        "variables maturite, sexe et", variable, "."
      )
    ))
  }



  # Cas sans variation de maturité exploitable ----
  etats_maturite <- unique(as.character(stats::na.omit(data_preparee$maturite)))

  if (!all(c("N", "O") %in% etats_maturite)) {
    return(list(
      success = FALSE,
      data = NULL,
      message = paste(
        "Les données exploitables ne contiennent pas à la fois des individus",
        "immatures et matures. La modélisation de la maturité est impossible."
      )
    ))
  }

  # Retour ----
  return(list(
    success = TRUE,
    data = data_preparee,
    message = NULL
  ))
}

