        tags$p(
          style = "margin: 0;",
          res$message
        )
      )
    })

    # Données du tableau ----
    table_masse_longueur <- reactive({

      res <- masse_longueur_res()

      req(isTRUE(res$success))
      req(!is.null(res$data))

      res$data
    })

    # Section graphique ----
    output$masse_longueur_plot_section <- renderUI({

      res <- masse_longueur_res()

      req(!is.null(res))

      if (!isTRUE(res$success) || is.null(res$plot)) {
        return(NULL)
      }

      tagList(
        br(),

        h3("Relation masse-longueur"),

        p(
          "La figure suivante représente la relation allométrique entre la longueur maximale (mm) ",
          "et la masse (g). L'équation et les paramètres estimés sont indiqués sur le graphique.",
        ),
        div(
          style = "max-width: 900px; margin: auto;",
          withSpinner(
            plotOutput(ns("plot"), height = "500px"),
            type = myspinner
          ),
          br(),
          downloadButton(ns("download_plot"), "Téléchargement du graphique")
        )
      )
    })

    # Section tableau ----
    output$masse_longueur_table_section <- renderUI({

      res <- masse_longueur_res()

      req(!is.null(res))

      if (!isTRUE(res$success) || is.null(res$flextable)) {
        return(NULL)
      }

      tagList(
        br(),
        h3("Tableau des coefficients"),
        uiOutput(ns("table_ui")),
        download_button_ui(ns("download_table"))
      )
    })

    # Affichage du graphique ----
    render_plot_ggplot(
      output_id = "plot",
      plot = reactive({
        res <- masse_longueur_res()

        req(isTRUE(res$success))
        req(!is.null(res$plot))

        res$plot
      })
    )

    # Téléchargement du graphique ----
    render_download_plot(
      id = "download_plot",
      plot = reactive({
        res <- masse_longueur_res()

        req(isTRUE(res$success))
        req(!is.null(res$plot))

        res$plot
      }),
      filename = reactive(
        build_export_filename(
          "masselongueur",
          filename_suffix(),
          ext = "png"
        )
      )
      )

    # Affichage du tableau ----
    render_table_flextable(
      "table_ui",
      reactive({
        res <- masse_longueur_res()

        req(isTRUE(res$success))
        req(!is.null(res$flextable))

        res$flextable
      })
    )

    # Téléchargement du tableau ----
    render_download_table(
      id = "download_table",
      data = table_masse_longueur,
      filename = reactive(
        build_export_filename("masselongueur", filename_suffix())
      )
    )
  })
}

#' maturite_a50 UI Function
#'
#' @description Module Shiny pour l'affichage des modèles A50.
#'
#' @param id Identifiant du module.
#'
#' @noRd
#'
#' @importFrom shiny NS uiOutput tabPanel
mod_maturite_a50_ui <- function(id) {
  ns <- NS(id)

  tabPanel(
    title = "Âge à maturité",
    uiOutput(ns("analysis_label")),
    uiOutput(ns("message_a50")),

    withSpinner(
      uiOutput(ns("section_a50_separes")),
      type = myspinner
    ),

    uiOutput(ns("section_a50_combine"))
  )
}

#' maturite_a50 Server Function
#'
#' @param id Identifiant du module.
#' @param specimen Expression réactive contenant les spécimens valides.
#' @param filename_suffix Expression réactive pour suffixe des fichiers à exporter.
#'
#' @noRd
mod_maturite_a50_server <- function(id, specimen, filename_suffix, analysis_label) {
  moduleServer(id, function(input, output, session) {
    ns <- session$ns

    output$analysis_label <- renderUI({
      req(analysis_label())

      div(
        analysis_label(),
        style = "
        margin-bottom: 15px;
        color: #555;"
      )
    })

    # ==== Résultat global ----
    table_modeles_a50_resultats <- reactive({
      req(specimen())

       maturite_compare_modele(
        specimen_data = specimen(),
        variable = "age"
      )

    })

    # ==== Disponibilité des modèles ----

    has_model_a50_f <- reactive({
      res <- table_modeles_a50_resultats()
      if (is.null(res$best_model)) {
        return(FALSE)
      }
      !is.null(res$best_model$best_model_F)})

    has_model_a50_m <- reactive({
      res <- table_modeles_a50_resultats()
      if (is.null(res$best_model)) {
        return(FALSE)
      }
      !is.null(res$best_model$best_model_M)})

    has_model_a50_comb <- reactive({
      res <- table_modeles_a50_resultats()
      if (is.null(res$best_model)) {
        return(FALSE)
      }
      !is.null(res$best_model$best_model_combined)})

        # ==== Affichage des modèles combinés ----

    afficher_modeles_combines_a50 <- reactive({
      has_model_a50_comb()
    })

    # ==== Message complémentaire ----

    message_complementaire_a50 <- reactive({
      res <- table_modeles_a50_resultats()
      req(!is.null(res))

      best_model <- res$best_model

      if (!has_model_a50_f() && !has_model_a50_m() && !has_model_a50_comb()) {
        return(
          HTML(
            "Les données disponibles ne permettent pas d'ajuster des modèles de maturité."
          )
        )
      }

      if (has_model_a50_f() || has_model_a50_m() || has_model_a50_comb()) {
        return(
          HTML(
            "Les résultats d'ajustement de différents modèles pour les femelles et les mâles séparés sont présentés ci-dessous. ",
            "<br>",
            "Les résultats des modèles pour les sexes combinés sont également présentés pour déterminer si du support statistique ",
            "est trouvé pour une différence.",
            "<br>",
            "Pour les dorés jaunes, un an a été ajouté à l'âge estimé des spécimens lors de la PENDJ pour bien représenter ",
            "l'âge de reproduction qui a lieu au printemps suivant."
          )
        )
      }
      NULL
    })

    # ==== Message UI ----
    output$message_a50 <- renderUI({
      res <- table_modeles_a50_resultats()
      req(!is.null(res))

      if (is.null(res$message) || identical(res$message, "")) {
        return(NULL)
      }

      couleur_bordure <- if (isTRUE(res$success)) "#4c6ef5" else "#c0392b"
      couleur_fond <- if (isTRUE(res$success)) "#f5f7ff" else "#fdf2f2"

      msg <- res$message

      div(
        style = paste(
          "margin: 15px 0;",
          "padding: 12px 16px;",
          "border-left: 4px solid", couleur_bordure, ";",
          "background-color:", couleur_fond
        ),
        tags$h4("Sélection des modèles A50"),
        tags$p(msg),
        tags$p(message_complementaire_a50())
      )
    })

    # ==== Tables de sélection ----
    table_a50_f <- reactive({
      table_modeles_a50_resultats()$table_sep_F$df
    })

    table_a50_m <- reactive({
      table_modeles_a50_resultats()$table_sep_M$df
    })

    table_a50_comb <- reactive({
      table_modeles_a50_resultats()$table_comb$df
    })

    # ==== Sélection des modèles ----
    default_index_a50_f <- reactive({
      table <- table_a50_f()
      req(nrow(table) > 0)

      comparaison <- table_modeles_a50_resultats()
      best_id <- comparaison$best_model$best_model_F

      idx <- which(table$modele_id == best_id)
      if (length(idx) == 0) return(1)
      idx[1]
    })

    default_index_a50_m <- reactive({
      table <- table_a50_m()
      req(nrow(table) > 0)

      comparaison <- table_modeles_a50_resultats()
      best_id <- comparaison$best_model$best_model_M

      idx <- which(table$modele_id == best_id)
      if (length(idx) == 0) return(1)
      idx[1]
    })

    default_index_a50_comb <- reactive({
      table <- table_a50_comb()
      req(nrow(table) > 0)

      comparaison <- table_modeles_a50_resultats()
      best_id <- comparaison$best_model$best_model_combined

      idx <- which(table$modele_id == best_id)
      if (length(idx) == 0) return(1)
      idx[1]
    })   

    selected_f <- reactive({
      req(has_model_a50_f())
      sel <- getReactableState("table_a50_f", "selected")

      if (is.null(sel)) {
        sel <- default_index_a50_f()
      }

      table_a50_f()[sel, "modele_id"]
    })

    selected_m <- reactive({
      req(has_model_a50_m())
      sel <- getReactableState("table_a50_m", "selected")

      if (is.null(sel)) {
        sel <- default_index_a50_m()
      }

      table_a50_m()[sel, "modele_id"]
    })

    selected_comb <- reactive({
      req(afficher_modeles_combines_a50())
      sel <- getReactableState("table_a50_comb", "selected")
      if (is.null(sel)) sel <- default_index_a50_comb()
      table_a50_comb()[sel, "modele_id"]
    })

    # ==== Résultats détaillés ----
    res_f <- reactive({
      req(has_model_a50_f())
      comparaison <- table_modeles_a50_resultats()
      modele_id <- selected_f()$modele_id
      best_glm <- comparaison$models_sep[[modele_id]]
      maturite_generate_modele(
        specimen(),
        variable = "age",
        modele = "TLO",
        lien = stringr::str_extract(
          modele_id,
          "logit|probit|cloglog"
        ),
        sexe = "F",
        modele_glm = best_glm
      )
    })

    res_m <- reactive({
      req(has_model_a50_m())
      comparaison <- table_modeles_a50_resultats()
      modele_id <- selected_m()$modele_id
      best_glm <- comparaison$models_sep[[modele_id]]
      maturite_generate_modele(
        specimen(),
        variable = "age",
        modele = "TLO",
        lien = stringr::str_extract(
          modele_id,
          "logit|probit|cloglog"
        ),
        sexe = "M",
        modele_glm = best_glm
      )
    })

    res_comb <- reactive({
      req(afficher_modeles_combines_a50())
      comparaison <- table_modeles_a50_resultats()
      modele_id <- selected_comb()$modele_id
      best_glm <- comparaison$models_comb[[modele_id]]
      maturite_generate_modele(
        specimen(),
        variable = "age",
        modele = stringr::str_extract(
          modele_id,
          "TLO|ADD|INT|COM"
        ),
        lien = stringr::str_extract(
          modele_id,
          "logit|probit|cloglog"
        ),
        sexe = NULL,
        modele_glm = best_glm
      )
    })


    # ==== Section modèles séparés ----
    output$section_a50_separes <- renderUI({

      if (
        !has_model_a50_f() &&
        !has_model_a50_m() &&
        !has_model_a50_comb()
      ) {
        return(NULL)
      }

      # ------------------------------------------------------------
      # Tableaux de comparaison des modèles
      # ------------------------------------------------------------

      table_f <- table_a50_f()
      table_m <- table_a50_m()

      tagList(

        tags$h3("Tableau de sélection des modèles - sexes séparés"),

        tags$p(
          "Comparaison des modèles ajustés séparément pour les femelles et les mâles."
        ),

        # ==========================================================
        # FEMELLES
        # ==========================================================

        tags$h4("Femelles"),

        if (has_model_a50_f()) {
          tagList(
            reactableOutput(ns("table_a50_f")),

            div(
              style = "margin: 10px 0 20px 0;",
              download_button_ui(ns("dl_a50_f"))
            )
          )

        } else {

          div(
            style = paste(
              "margin: 10px 0 20px 0;",
              "padding: 12px 16px;",
              "border-left: 4px solid #c0392b;",
              "background-color: #fdf2f2;"
            ),
            "Aucun modèle valide n'est disponible pour les femelles."
          )
        },

        tags$hr(),

        # ==========================================================
        # MÂLES
        # ==========================================================

        tags$h4("Mâles"),

        if (has_model_a50_m()) {

          tagList(
            reactableOutput(ns("table_a50_m")),

            div(
              style = "margin: 10px 0 20px 0;",
