          # --------------------------------------------------------

          column(
            width = 6,

            if (has_model_a50_f()) {

              tagList(
                plotOutput(
                  ns("plot_a50_f"),
                  height = "500px"
                ),

                div(
                  style = "margin-top: 10px;",
                  downloadButton(
                    ns("dl_plot_a50_f"),
                    "Télécharger"
                  )
                )
              )

            } else {

              div(
                style = paste(
                  "margin: 10px 0;",
                  "padding: 12px 16px;",
                  "border-left: 4px solid #c0392b;",
                  "background-color: #fdf2f2;"
                ),
                "Aucun graphique disponible pour les femelles."
              )
            }
          ),

          # --------------------------------------------------------
          # Mâles
          # --------------------------------------------------------

          column(
            width = 6,

            if (has_model_a50_m()) {

              tagList(
                plotOutput(
                  ns("plot_a50_m"),
                  height = "500px"
                ),

                div(
                  style = "margin-top: 10px;",
                  downloadButton(
                    ns("dl_plot_a50_m"),
                    "Télécharger"
                  )
                )
              )

            } else {

              div(
                style = paste(
                  "margin: 10px 0;",
                  "padding: 12px 16px;",
                  "border-left: 4px solid #c0392b;",
                  "background-color: #fdf2f2;"
                ),
                "Aucun graphique disponible pour les mâles."
              )
            }
          )
        ),

        tags$hr(
          style = "margin: 30px 0;"
        )
      )
    })


    # ==============================================================
    # Tableau de comparaison des modèles — FEMELLES
    # ==============================================================

    output$table_a50_f <- renderReactable({

      req(has_model_a50_f())

      idx <- default_index_a50_f()

      reactable(
        as.data.frame(table_a50_f()),

        selection = "single",

        defaultSelected = if (is.na(idx)) NULL else idx,

        pagination = FALSE,
        showPageInfo = FALSE,
        compact = TRUE,
        outlined = TRUE,
        defaultPageSize = 20,

        onClick = "select",

        defaultColDef = colDef(
          align = "center",
          headerStyle = list(
            textAlign = "center"
