    # ==== Section combinée ----
    output$section_a50_combine <- renderUI({

      if (!afficher_modeles_combines_a50()) {
        return(
          tagList(
            tags$h3("Tableau de sélection des modèles - sexes combinés"),

            div(
              style = paste(
                "margin: 10px 0 20px 0;",
