      if (length(idx) == 0) return(1)
      idx[1]
    })

    default_index_l50_comb <- reactive({
      table <- table_l50_comb()
      req(nrow(table) > 0)

      comparaison <- table_modeles_l50_resultats()
      best_id <- comparaison$best_model$best_model_combined

