#' Appliquer la méthode de Chapman-Robson pour estimer Z et A
#'
#' Cette fonction applique la méthode Chapman-Robson via
#' `fishmethods::agesurv()` pour estimer le coefficient de mortalité (`Z`) à
#' partir d'une distribution d'âge, puis calcule le taux de mortalité (`A`).
#' Elle retourne à la fois un tableau brut (`data.frame`) et une version
#' formatée (`flextable`).
#'
#' La fonction retourne toujours une liste structurée contenant :
#' \itemize{
#'   \item `success` : indicateur logique de réussite
#'   \item `message` : message informatif si le calcul est impossible
#'   \item `data` : tableau brut des estimations, ou `NULL`
#'   \item `flextable` : tableau formaté, ou `NULL`
#' }
#'
#' @param specimen Un `data.frame` contenant une colonne `age`.
#' @param pp Valeur de "peak-plus", soit la classe d'âge au-delà de laquelle les
#'   âges sont regroupés.
#' @param age_max Âge maximum à considérer dans le calcul.
#'
#' @return Une liste contenant :
#' \describe{
#'   \item{success}{Un booléen indiquant si l'estimation a réussi.}
#'   \item{message}{Un message informatif si l'estimation est impossible, sinon `NULL`.}
#'   \item{data}{Un `data.frame` contenant les colonnes `z`, `se`, `a`, `ic_95`, ou `NULL`.}
#'   \item{flextable}{Une version formatée du tableau, prête à être affichée ou exportée, ou `NULL`.}
#' }
#'
#' @importFrom fishmethods agesurv
#' @importFrom dplyr transmute filter
#' @importFrom flextable flextable set_caption set_header_labels
#' @importFrom glue glue
#'
#' @export
#'
#' @examples
#' fake_data <- data.frame(age = c(2, 3, 3, 4, 4, 4, 5, 5, 6))
#' mort <- mortalite_chaprob(fake_data, pp = 3, age_max = 6)
#' mort$data
#' mort$flextable
mortalite_chaprob <- function(specimen, pp, age_max) {
  # Validation de base ====
  if (is.null(specimen) || !is.data.frame(specimen) || nrow(specimen) == 0) {
    return(list(
      success = FALSE,
      message = "Aucune donnée n'est disponible pour appliquer la méthode de Chapman-Robson.",
      data = NULL,
      flextable = NULL
    ))
  }

  if (!"age" %in% names(specimen)) {
    return(list(
      success = FALSE,
      message = "La colonne `age` est requise pour appliquer la méthode de Chapman-Robson.",
      data = NULL,
      flextable = NULL
    ))
  }

  if (is.null(pp) || length(pp) != 1 || is.na(pp) || !is.numeric(pp) || pp <= 0) {
    return(list(
      success = FALSE,
      message = "L'argument `pp` doit être un numérique strictement positif.",
      data = NULL,
      flextable = NULL
    ))
  }

  if (is.null(age_max) || length(age_max) != 1 || is.na(age_max) || !is.numeric(age_max) || age_max <= 0) {
    return(list(
      success = FALSE,
      message = "L'argument `age_max` doit être un numérique strictement positif.",
      data = NULL,
      flextable = NULL
    ))
  }

  if (pp >= age_max) {
    return(list(
      success = FALSE,
      message = "La méthode Chapman-Robson requiert un `pp` strictement inférieur à `age_max`.",
      data = NULL,
      flextable = NULL
    ))
  }

  # Préparation des données ====
  data_age <- specimen |>
    filter(!is.na(.data$age))

  if (nrow(data_age) == 0) {
    return(list(
      success = FALSE,
      message = "Aucune donnée d'âge valide n'est disponible pour Chapman-Robson.",
      data = NULL,
      flextable = NULL
    ))
  }

  if (length(unique(data_age$age)) < 2) {
    return(list(
      success = FALSE,
      message = "La méthode Chapman-Robson nécessite au moins deux classes d'âge différentes.",
      data = NULL,
      flextable = NULL
    ))
  }

  # Application de la méthode Chapman-Robson ====
  res_cr <- tryCatch(
    agesurv(
      type = 1,
      age = data_age$age,
      full = pp,
      last = age_max,
      estimate = "z",
      method = "cr"
    ),
    error = function(e) NULL
  )

  if (is.null(res_cr) || is.null(res_cr$results) || nrow(res_cr$results) == 0) {
    return(list(
      success = FALSE,
      message = "L'estimation Chapman-Robson n'a pas pu être calculée pour ce jeu de données.",
      data = NULL,
      flextable = NULL
    ))
  }

  # Construction du tableau brut ====
  table_resultats <- tryCatch(
    {
      res_cr$results |>
        transmute(
          z = .data$Estimate,
          se = .data$SE,
          a = round((1 - exp(-.data$z)) * 100, 1),
          ic_95 = {

            lower <- format(
              round((1 - exp(-(.data$z - 1.96 * .data$se))) * 100, 1),
              nsmall = 1,
              decimal.mark = ","
            )

            upper <- format(
              round((1 - exp(-(.data$z + 1.96 * .data$se))) * 100, 1),
              nsmall = 1,
              decimal.mark = ","
            )

            glue("[{lower} – {upper}]")
          }
        )
    },
    error = function(e) NULL
  )

  if (is.null(table_resultats) || nrow(table_resultats) == 0) {
    return(list(
      success = FALSE,
      message = "Les résultats Chapman-Robson n'ont pas pu être mis en forme.",
      data = NULL,
      flextable = NULL
    ))
  }

  # Mise en forme flextable ====
  tableau_formate <- tryCatch(
    {
      flextable(table_resultats) |>
        set_caption("Estimation de la mortalité par la méthode de Chapman-Robson") |>
        set_header_labels(
          z = "Coefficient de mortalité (Z)",
          se = "Erreur standard",
          a = "Taux de mortalité (A %)",
          ic_95 = "IC 95 % (%)"
        ) |>
        style_flextable_aquapop()|>
        colformat_double(j = "z", digits = 3, decimal.mark = ",", big.mark =  " ") |>
        colformat_double(j = "se", digits = 3, decimal.mark = ",", big.mark =  " ") |>
        colformat_double(j = "a", digits = 1, decimal.mark = ",", big.mark =  " ")
    },
    error = function(e) NULL
  )

  list(
    success = TRUE,
    message = NULL,
    data = table_resultats,
    flextable = tableau_formate
  )
}

#' Extraire le modèle de mortalité correspondant à la meilleure méthode sélectionnée
#'
#' Cette fonction ajuste le modèle de mortalité correspondant à la méthode
#' sélectionnée. Si `methode` n'est pas précisée, elle compare d'abord les
#' modèles disponibles à l'aide de `mortalite_compare_modele()` puis sélectionne
#' automatiquement le meilleur via `mortalite_select_best_modele()`.
#'
#' La fonction retourne `NULL` si aucun modèle ne peut être sélectionné ou ajusté.
#'
#' @param data Un `data.frame` contenant au minimum les colonnes `age` et `number`,
#'   généralement produit par `mortalite_prepare_extended()`.
#' @param methode Chaîne de caractères optionnelle parmi `"poisson"`, `"nb1"`,
#'   `"nb2"`, `"cmp"` ou `"gp"`. Si précisée, ce modèle est ajusté directement
#'   sans étape de comparaison.
#'
#' @return Un objet de classe `glm`, `glm.nb` ou `glmmTMB`, selon la méthode
#'   choisie, ou `NULL` si aucun modèle n'a pu être ajusté.
#'
#' @importFrom glmmTMB compois genpois glmmTMB nbinom1
#' @importFrom MASS glm.nb
#'
#' @export
mortalite_fit_best_modele <- function(data, methode = NULL) {
  # Validation de base ====
  if (is.null(data) || !is.data.frame(data) || nrow(data) == 0) {
    return(NULL)
  }

  if (!all(c("age", "number") %in% names(data))) {
    return(NULL)
  }

  # Déterminer la méthode si elle n'est pas fournie ====
  if (is.null(methode)) {
    res_compare <- mortalite_compare_modele(data = data)

    if (is.null(res_compare) || isFALSE(res_compare$success) || is.null(res_compare$data)) {
      return(NULL)
    }

    methode <- mortalite_select_best_modele(res_compare$data)
  }

  # Validation de la méthode ====
  methodes_valides <- c("poisson", "nb1", "nb2", "cmp", "gp")

  if (is.null(methode) || !methode %in% methodes_valides) {
    return(NULL)
  }

  # Ajuster le modèle selon la méthode sélectionnée ====
  model <- switch(
    methode,
    poisson = tryCatch(
      glm(number ~ age, family = poisson, data = data),
      error = function(e) NULL
    ),
    nb1 = tryCatch(
      glmmTMB(number ~ age, family = nbinom1(), data = data),
      error = function(e) NULL
    ),
    nb2 = tryCatch(
      glm.nb(number ~ age, data = data),
      error = function(e) NULL
    ),
    cmp = tryCatch(
      glmmTMB(number ~ age, family = compois(), data = data),
      error = function(e) NULL
    ),
    gp = tryCatch(
      glmmTMB(number ~ age, family = genpois(), data = data),
      error = function(e) NULL
    )
  )

  model
}

# ==== helper mortalité - test HNP CMP =========================================

#' Exécuter le test HNP pour un modèle CMP
#'
#' Cette fonction interne applique le schéma HNP utilisé dans les modèles de
#' mortalité : 2 simulations initiales, puis 3 simulations additionnelles si
#' l'ajustement est marginal (entre 10 et 15 % d'observations hors bande).
#'
#' La fonction retourne toujours un `data.frame` d'une ligne. Si le modèle ne
#' peut pas être ajusté ou si certaines statistiques ne peuvent pas être
#' calculées, les valeurs correspondantes sont retournées à `NA` et
#' `convergence = FALSE`.
#'
#' @param model Objet modèle ajusté avec `glmmTMB`.
#' @param df_age_etendue Un `data.frame` contenant les colonnes `age` et `number`.
#' @param max_refit_attempts Nombre maximal d'essais permis dans la fonction
#'   interne de réajustement utilisée par `hnp()`.
#'
#' @return Une liste contenant :
#' \describe{
#'  Un `data.frame` d'une ligne contenant :
#' \describe{
#'   \item{methode}{Modèle utilisé (`"gp"`).}
#'   \item{ajustement_hnp}{Pourcentage moyen d'observations hors bande (HNP).}
#'   \item{aicc}{Critère d'information corrigé (AICc).}
#'   \item{Z}{Coefficient d'âge (valeur absolue).}
#'   \item{SE}{Erreur standard de `Z`.}
#'   \item{A}{Taux de mortalité annuel estimé en pourcentage.}
#'   \item{ic95}{Intervalle de confiance approximatif de `A`.}
#'   \item{commentaire}{Appréciation qualitative de l'ajustement ou message d'échec.}
#'   \item{convergence}{Booléen indiquant si le modèle a convergé.}
#'   \item{nb_iterations_hnp}{Nombre d'itérations HNP effectuées.}
#'   Un `plot` : graphique des résidus du test hnp, ou `NULL`
#' }
#'
#' @importFrom glmmTMB glmmTMB nbinom1
#' @importFrom hnp hnp
#' @importFrom stats residuals simulate
#' @noRd
#' @keywords internal


   # Fonctions de base pour CMP  ====
diagfun_cmp <- function(obj) {
  residuals(obj, type = "pearson")
}

simfun_cmp <- function(n, obj) {
  simulate(obj)[[1]]
}

make_fitfun_cmp <- function(df_age_etendue, model, max_refit_attempts = 10L) {

  function(y) {

    attempt <- 1L

    fit <- try(
      glmmTMB(
        y ~ age,
        family = compois(link = "log"),
        data = df_age_etendue
      ),
      silent = TRUE
    )

    while (inherits(fit, "try-error") &&
           attempt < max_refit_attempts) {

      y_retry <- try(simulate(model)[[1]], silent = TRUE)

      if (inherits(y_retry, "try-error")) {
        return(NULL)
      }

      fit <- try(
        glmmTMB(
          y_retry ~ age,
          family = compois(link = "log"),
          data = df_age_etendue
        ),
        silent = TRUE
      )

      attempt <- attempt + 1L
    }

    if (inherits(fit, "try-error")) {
      return(NULL)
    }

    fit
  }
}

# Test HNP  ====
simuler_hnp_cmp <- function(model, df_age_etendue, n_iter){

  fitfun_cmp <- make_fitfun_cmp(
    df_age_etendue = df_age_etendue,
    model = model
  )

  set.seed(2023)

  resultats_hnp <- replicate(
    n_iter,
    hnp(
      model,
      newclass = TRUE,
      diagfun = diagfun_cmp,
      simfun = simfun_cmp,
      fitfun = fitfun_cmp,
      how.many.out = TRUE,
      plot.sim = FALSE
    ),
    simplify = FALSE
  )

  list(
    hnp = resultats_hnp,
    pct = sapply(
      resultats_hnp,
      function(x) x$out / x$total * 100
    )
  )
}

run_hnp_cmp <- function(model, df_age_etendue){

  test_hnp(
    simuler = simuler_hnp_cmp,
    model = model,
    df_age_etendue = df_age_etendue
  )

}




# ==== modèle mortalité CMP ====================================================

#' Ajuster un modèle de mortalité de type CMP (Conway-Maxwell-Poisson)
#'
#' Cette fonction ajuste un modèle CMP (`glmmTMB`) sur des données de fréquence
#' d'âge étendues. Elle applique un test HNP (Half-Normal Plot) avec 2 à
#' 5 simulations pour évaluer la qualité de l'ajustement, puis retourne les
#' paramètres estimés, le taux de mortalité annuel, et un commentaire sur
#' l'ajustement.
#'
#' Dans cette version refactorisée, la logique est rendue plus robuste :
#' \itemize{
#'   \item les cas d'échec retournent une ligne standardisée plutôt qu'une erreur;
#'   \item la boucle de réajustement utilisée dans le test HNP est bornée;
#'   \item la logique HNP est isolée dans une fonction interne dédiée.
#' }
#'
#' @param df_age_etendue Un `data.frame` produit par `mortalite_prepare_extended()`
#'   contenant au minimum :
#' \describe{
#'   \item{age}{Âge des individus (entier)}
#'   \item{number}{Nombre d'individus observés à cet âge}
#' }
#'
#' @return Un `data.frame` d'une ligne contenant :
#' \describe{
#'   \item{methode}{Type de modèle (`"cmp"`)}
#'   \item{ajustement_hnp}{Pourcentage moyen d'observations hors bande (test HNP)}
#'   \item{aicc}{Critère d'information corrigé (AICc)}
#'   \item{Z}{Coefficient de régression sur l'âge}
#'   \item{SE}{Erreur standard associée à `Z`}
#'   \item{A}{Taux de mortalité annuel estimé (%)}
#'   \item{ic95}{Intervalle de confiance de `A`}
#'   \item{commentaire}{Appréciation qualitative de l'ajustement}
#'   \item{convergence}{Convergence interprétable du modèle (booléen)}
#'   \item{nb_iterations_hnp}{Nombre de simulations HNP effectuées (2 ou 5)}
#' }
#'
#' @examples
#' df_fake <- tibble::tibble(age = 1:6, number = c(180, 120, 70, 40, 25, 10))
#' mortalite_fit_modele_cmp(df_fake)
#'
#' @importFrom dplyr case_when
#' @importFrom MuMIn AICc
#' @importFrom glue glue
#' @importFrom glmmTMB compois glmmTMB
#' @importFrom tibble tibble
#' @export
mortalite_fit_modele_cmp <- function(df_age_etendue) {
  # Validation de base ====
  if (is.null(df_age_etendue) || !is.data.frame(df_age_etendue) || nrow(df_age_etendue) == 0) {
    return(list(
      tableau = tibble(
        methode = "cmp",
        ajustement_hnp = NA_real_,
        aicc = NA_real_,
        Z = NA_real_,
        SE = NA_real_,
        A = NA_real_,
        ic95 = NA_character_,
        commentaire = "Aucune donnée disponible pour ajuster le modèle.",
        convergence = FALSE,
        nb_iterations_hnp = NA_real_
      ),
      graph_hnp = NULL
    ))
  }

  if (!all(c("age", "number") %in% names(df_age_etendue))) {
    return(list(
      tableau = tibble(
        methode = "cmp",
        ajustement_hnp = NA_real_,
        aicc = NA_real_,
        Z = NA_real_,
        SE = NA_real_,
        A = NA_real_,
        ic95 = NA_character_,
        commentaire = "Les colonnes `age` et `number` sont requises.",
        convergence = FALSE,
        nb_iterations_hnp = NA_real_
      ),
      graph_hnp = NULL
    ))
  }

  if (nrow(df_age_etendue) < 2 || length(unique(df_age_etendue$age)) < 2) {
    return(list(
      tableau = tibble(
        methode = "cmp",
        ajustement_hnp = NA_real_,
        aicc = NA_real_,
        Z = NA_real_,
        SE = NA_real_,
        A = NA_real_,
        ic95 = NA_character_,
        commentaire = "Le modèle requiert au moins deux âges distincts.",
        convergence = FALSE,
        nb_iterations_hnp = NA_real_
      ),
      graph_hnp = NULL
    ))
  }

  # Ajustement du modèle CMP ====
  model <- tryCatch(
    glmmTMB(
      number ~ age,
      family = compois(link = "log"),
      data = df_age_etendue
    ),
    error = function(e) NULL
  )

  if (is.null(model)) {
    return(list(
      tableau = tibble(
        methode = "cmp",
        ajustement_hnp = NA_real_,
        aicc = NA_real_,
        Z = NA_real_,
        SE = NA_real_,
        A = NA_real_,
        ic95 = NA_character_,
        commentaire = "Le modèle n'a pas pu être ajusté.",
        convergence = FALSE,
        nb_iterations_hnp = NA_real_
      ),
      graph_hnp = NULL
    ))
  }

  convergence_modele <- isTRUE(model$fit$convergence == 0)

  hnp_res <- run_hnp_cmp(
    model = model,
    df_age_etendue = df_age_etendue
  )

  graph_hnp <- hnp_res$graph_hnp

  coef_table <- tryCatch(
    summary(model)$coefficients$cond,
    error = function(e) NULL
  )

  if (is.null(coef_table) || !("age" %in% rownames(coef_table))) {
    return(list(
      tableau = tibble(
      methode = "cmp",
      ajustement_hnp = hnp_res$ajustement_hnp,
      aicc = tryCatch(AICc(model), error = function(e) NA_real_),
      Z = NA_real_,
      SE = NA_real_,
      A = NA_real_,
      ic95 = NA_character_,
      commentaire = "Le modèle a été ajusté, mais les paramètres n'ont pas pu être extraits.",
      convergence = FALSE,
      nb_iterations_hnp = hnp_res$nb_iterations_hnp
      ),
      graph_hnp = graph_hnp
      ))
  }

  Z <- abs(coef_table["age", "Estimate"])
  SE <- coef_table["age", "Std. Error"]

  # Conversion en taux de mortalité annuel ====
  A <- (1 - exp(-Z)) * 100
  IC <- confint(model)["age", ] 
  lowerZ <- -IC[2]
  upperZ <- -IC[1]
  lowerA <- round((1 - exp(-lowerZ)) * 100, 1)
  upperA <- round((1 - exp(-upperZ)) * 100, 1)
  ic_95 <- glue("[{lowerA} – {upperA}]") |>
    gsub("\\.", ",", x = _)

  commentaire <- case_when(
    is.na(hnp_res$ajustement_hnp) ~ "Modèle ajusté, mais test HNP non calculable.",
    hnp_res$ajustement_hnp < 10 ~ "Bon ajustement",
    hnp_res$ajustement_hnp < 15 ~ "Ajustement marginal",
    TRUE ~ "Mauvais ajustement"
  )

  resultat <- tibble(
    methode = "cmp",
    ajustement_hnp = hnp_res$ajustement_hnp,
    aicc = tryCatch(AICc(model), error = function(e) NA_real_),
    Z = round(Z, 4),
    SE = round(SE, 4),
    A = round(A, 1),
    ic95 = ic_95,
    commentaire = commentaire,
    convergence = convergence_modele,
    nb_iterations_hnp = hnp_res$nb_iterations_hnp
    )

  list(
    tableau = resultat,
    graph_hnp = graph_hnp
  )
}

#' Trouver l'âge maximal dans les données de mortalité
#'
#' Cette fonction détermine l'âge maximal observé dans les données de mortalité,
#' en ignorant les valeurs manquantes de la colonne `age`.
#'
#' La fonction retourne toujours une liste structurée contenant :
#' \itemize{
#'   \item `success` : indicateur logique de réussite
#'   \item `message` : message informatif si le calcul est impossible
#'   \item `value` : âge maximal observé, ou `NULL` si indisponible
#' }
#'
#' La fonction retourne `success = FALSE` dans les cas suivants :
#' \itemize{
#'   \item les données sont `NULL` ou ne sont pas un `data.frame`
#'   \item la colonne `age` est absente
#'   \item aucun âge valide n'est disponible
#' }
#'
#' @param data Un `data.frame` contenant les données de spécimens. Doit inclure
#'   une colonne nommée `age` de type numérique ou entier.
#'
#' @return Une liste avec les éléments suivants :
#' \describe{
#'   \item{success}{Un booléen indiquant si le calcul a réussi.}
#'   \item{message}{Un message informatif si le calcul est impossible, sinon `NULL`.}
#'   \item{value}{Un entier correspondant à l'âge maximal observé, ou `NULL` si le calcul est impossible.}
#' }
#'
#' @examples
#' # Exemple avec des âges valides
#' df <- data.frame(age = c(1, 2, 3, NA, 4))
#' mortalite_get_age_max(df)
#'
#' # Exemple sans âges valides
#' df2 <- data.frame(age = c(NA, NA))
#' mortalite_get_age_max(df2)
#'
#' # Exemple sans colonne 'age'
#' mortalite_get_age_max(data.frame(other = 1:5))
#'
#' @export
mortalite_get_age_max <- function(data) {
  # Validation de base ====
  if (is.null(data) || !is.data.frame(data)) {
    return(list(
      success = FALSE,
      message = "Les données fournies sont invalides.",
      value = NULL
    ))
  }

  if (!"age" %in% names(data)) {
    return(list(
      success = FALSE,
      message = "La colonne `age` est absente des données.",
      value = NULL
    ))
  }

  if (nrow(data) == 0) {
    return(list(
      success = FALSE,
      message = "Aucun spécimen n'est disponible pour déterminer l'âge maximal.",
      value = NULL
    ))
  }

  # Nettoyage des âges ====
  ages_clean <- na.omit(data$age)

  if (length(ages_clean) == 0) {
    return(list(
      success = FALSE,
      message = "Aucun âge valide n'est disponible pour déterminer l'âge maximal.",
      value = NULL
    ))
  }

  # Sortie ====
  list(
    success = TRUE,
    message = NULL,
    value = max(ages_clean)
  )
}

#' Déterminer l'âge Peak Plus (âge de départ) à partir de la structure d'âge
#'
#' Cette fonction détermine l'âge de départ (`peak plus`) utilisé dans l'analyse
#' de mortalité à partir de la structure d'âge observée. Elle identifie l'âge le
#' plus fréquent (le mode) dans la colonne `age`, puis ajoute 1 à cette valeur.
#'
#' La fonction retourne toujours une liste structurée contenant :
#' \itemize{
#'   \item `success` : indicateur logique de réussite
#'   \item `message` : message informatif si le calcul est impossible
#'   \item `value` : valeur numérique de l'âge Peak Plus, ou `NULL` si indisponible
#' }
#'
#' Règles appliquées :
#' \itemize{
#'   \item les valeurs manquantes (`NA`) sont ignorées
#'   \item si plusieurs âges partagent la fréquence maximale, le plus petit âge est retenu
#'   \item si aucune donnée exploitable n'est disponible, la fonction retourne
#'   `success = FALSE` et `value = NULL`
#'   \item si la colonne `age` est absente, la fonction retourne aussi
#'   `success = FALSE`
#' }
#'
#' @param data Un `data.frame` contenant une colonne `age`, de type numérique ou entier.
#'
#' @return Une liste avec les éléments suivants :
#' \describe{
#'   \item{success}{Un booléen indiquant si le calcul a réussi.}
#'   \item{message}{Un message informatif si le calcul est impossible, sinon `NULL`.}
#'   \item{value}{Un entier correspondant au Peak Plus, ou `NULL` si le calcul est impossible.}
#' }
#'
#' @importFrom stats na.omit
#'
#' @export
#'
#' @examples
#' # Jeu de données simple avec un mode clair
#' df <- data.frame(age = c(1, 2, 2, 3, 3, 3, 4))
#' mortalite_get_peak_plus(df)
#'
#' # Cas avec ex aequo : le plus petit âge est retenu
#' df <- data.frame(age = c(2, 2, 3, 3))
#' mortalite_get_peak_plus(df)
#'
#' # Données avec NA
#' df <- data.frame(age = c(NA, 2, 2, NA, 3))
#' mortalite_get_peak_plus(df)
#'
#' # Données vides ou toutes manquantes
#' mortalite_get_peak_plus(data.frame(age = numeric(0)))
#' mortalite_get_peak_plus(data.frame(age = c(NA, NA)))
mortalite_get_peak_plus <- function(data, sp) {

    # Validation des données ====
  if (is.null(data) || !is.data.frame(data)) {
    return(list(
      success = FALSE,
      message = "Les données fournies sont invalides.",
      value = NULL
    ))
  }

  if (!"age" %in% names(data)) {
    return(list(
      success = FALSE,
      message = "La colonne `age` est absente des données.",
      value = NULL
    ))
  }

  if (nrow(data) == 0) {
    return(list(
      success = FALSE,
      message = "Aucun spécimen n'est disponible pour déterminer l'âge Peak Plus.",
      value = NULL
    ))
  }

  # Validation de l'espèce
  if (is.null(sp) ||
      !is.character(sp) ||
      length(sp) != 1 ||
      is.na(sp) ||
      sp == "") {

    return(list(
      success = FALSE,
      message = "Le code d'espèce n'est pas valide.",
      value = NULL
    ))
  }

  # Déterminer l'ajustement selon l'espèce
  if (sp == "SAFO") {
    increment <- 0L
  } else if (sp %in% c("SANA", "SAVI")) {
    increment <- 1L
  } else {
    return(list(
      success = FALSE,
      message = paste0(
        "Aucune règle Peak Plus n'est définie pour l'espèce `",
        sp,
        "`."
      ),
      value = NULL
    ))
  }

  # Nettoyage des âges ====
  ages_clean <- na.omit(data$age)

  if (length(ages_clean) == 0) {
    return(list(
      success = FALSE,
      message = "Aucun âge valide n'est disponible pour déterminer l'âge Peak Plus.",
      value = NULL
    ))
  }

  # Calcul du mode et du peak plus ====
  age_table <- table(ages_clean)
  mode_age <- as.integer(names(age_table)[age_table == max(age_table)]) |> min()

  peak_plus <- mode_age + increment

  # Sortie ====
  list(
    success = TRUE,
    message = NULL,
    value = peak_plus,
    sp = sp,
    mode_age = mode_age
  )
}

#' Générer une phrase descriptive pour le modèle de mortalité sélectionné
#'
#' Cette fonction génère une phrase interprétative à partir du modèle de
#' mortalité sélectionné et de la table de comparaison des modèles.
#'
#' Elle retourne `NULL` si les informations nécessaires ne sont pas disponibles.
#'
#' @param data_comparaison Un `data.frame` contenant au minimum les colonnes
#'   `methode` et `A`, généralement issu de `mortalite_compare_modele()$data`.
#' @param modele_nom Nom du modèle à décrire (ex: `"nb1"`).
#'
#' @return Une chaîne de caractères résumant le modèle et la mortalité annuelle,
#'   ou `NULL` si la phrase ne peut pas être générée.
#'
#' @importFrom glue glue
#'
#' @export
#'
#' @examples
#' df <- data.frame(methode = c("nb1", "poisson"), A = c(37, 51))
#' mortalite_phrase_resume(df, "nb1")
mortalite_phrase_resume <- function(data_comparaison, modele_nom) {
  # Validation de base ====
  if (is.null(modele_nom) || length(modele_nom) != 1 || is.na(modele_nom) || modele_nom == "") {
    return(NULL)
  }

  if (is.null(data_comparaison) || !is.data.frame(data_comparaison) || nrow(data_comparaison) == 0) {
    return(NULL)
  }

  if (!"methode" %in% names(data_comparaison)) {
    return(NULL)
  }

  # Trouver la ligne du modèle ====
  ligne <- data_comparaison[data_comparaison$methode == modele_nom, , drop = FALSE]

  if (nrow(ligne) == 0) {
    return(NULL)
  }

  modele_upper <- toupper(modele_nom)

  # Cas sans estimation de A ====
  if (!"A" %in% names(ligne) || is.na(ligne$A[1])) {
    return(
      glue("Le modèle {modele_upper} a été sélectionné, mais la mortalité annuelle n'est pas disponible.") |>
        as.character()
    )
  }

  # Phrase complète ====
  glue(
    "Le modèle {modele_upper} décrit le mieux la mortalité de la population. ",
    "La mortalité annuelle s'élève à {ligne$A[1]} %."
  ) |>
    as.character()
}

#' Préparer les données corrigées de fréquence d'âge pour l'estimation de la mortalité
#'
#' Cette fonction applique `agesurv()` avec `type = 1` pour générer les données
#' individuelles de fréquence d'âge sur la partie descendante de la courbe de capture.
#' Elle filtre d'abord les spécimens ayant un âge valide, applique l'estimation,
#' puis complète les classes d'âge manquantes avec des zéros pour produire une
#' table uniforme.
#'
#' La fonction retourne toujours une liste structurée contenant :
#' \itemize{
#'   \item `success` : indicateur logique de réussite
#'   \item `message` : message informatif si la préparation est impossible
#'   \item `data` : tableau de fréquences corrigées, ou `NULL` si indisponible
#' }
#'
#' @param data Un `data.frame` contenant les spécimens d'une seule espèce, avec
#'   une colonne nommée `age`. Les valeurs manquantes (`NA`) sont automatiquement exclues.
#' @param age_peak_plus Un entier indiquant l'âge à partir duquel commence
#'   l'analyse de mortalité.
#' @param age_max Un entier indiquant l'âge maximum à considérer pour
#'   l'estimation de la mortalité.
#'
#' @return Une liste avec les éléments suivants :
#' \describe{
#'   \item{success}{Un booléen indiquant si la préparation a réussi.}
#'   \item{message}{Un message informatif si la préparation est impossible, sinon `NULL`.}
#'   \item{data}{Un `data.frame` contenant les colonnes `age` et `number`, ou `NULL` si la préparation est impossible.}
#' }
#'
#' @importFrom dplyr arrange
#' @importFrom dplyr filter
#' @importFrom dplyr left_join
#' @importFrom dplyr mutate
#' @importFrom fishmethods agesurv
#' @importFrom tibble tibble
#' @importFrom tidyr replace_na
#'
#' @export
#'
#' @examples
#' data_exemple <- data.frame(age = c(2, 3, 3, 4, 5, 5, 5, 6, 7, NA))
#' mortalite_prepare_corr(data = data_exemple, age_peak_plus = 5, age_max = 7)
mortalite_prepare_corr <- function(data, age_peak_plus, age_max) {
  # Validation de base ====
  if (is.null(data) || !is.data.frame(data)) {
    return(list(
      success = FALSE,
      message = "Les données fournies sont invalides.",
      data = NULL
    ))
  }

  if (!"age" %in% names(data)) {
    return(list(
      success = FALSE,
      message = "La colonne `age` est absente des données.",
      data = NULL
    ))
  }

  if (nrow(data) == 0) {
    return(list(
      success = FALSE,
      message = "Aucun spécimen n'est disponible pour préparer les données de mortalité.",
      data = NULL
    ))
  }

  if (is.null(age_peak_plus) || length(age_peak_plus) != 1 || is.na(age_peak_plus)) {
    return(list(
      success = FALSE,
      message = "L'âge de départ (`age_peak_plus`) est invalide ou manquant.",
      data = NULL
    ))
  }

  if (is.null(age_max) || length(age_max) != 1 || is.na(age_max)) {
    return(list(
      success = FALSE,
      message = "L'âge maximal (`age_max`) est invalide ou manquant.",
      data = NULL
    ))
  }

  if (!is.numeric(age_peak_plus) || !is.numeric(age_max)) {
    return(list(
      success = FALSE,
      message = "Les arguments `age_peak_plus` et `age_max` doivent être numériques.",
      data = NULL
    ))
  }

  if (age_peak_plus < 0 || age_max < 0) {
    return(list(
      success = FALSE,
      message = "Les âges doivent être supérieurs ou égaux à 0.",
      data = NULL
    ))
  }

  # Nettoyage des âges ====
  data_valid <- data |>
    filter(!is.na(.data$age))

  if (nrow(data_valid) == 0) {
    return(list(
      success = FALSE,
      message = "Aucune valeur d'âge valide n'est disponible après suppression des NA.",
      data = NULL
    ))
  }

  age_observe_max <- max(data_valid$age)

  if (age_peak_plus > age_observe_max) {
    return(list(
      success = FALSE,
      message = "`age_peak_plus` est supérieur à l'âge maximum observé dans les données.",
      data = NULL
    ))
  }

  if (age_peak_plus >= age_max) {
    return(list(
      success = FALSE,
      message = paste(
        "L'âge de départ doit être strictement inférieur à l'âge maximal.",
        "Veuillez choisir manuellement une valeur de `age_peak_plus` plus petite."
      ),
      data = NULL
    ))
  }

  # Estimation avec agesurv ====
  resultat <- tryCatch(
    agesurv(
      type = 1,
      age = data_valid$age,
      full = age_peak_plus,
      last = age_max,
      estimate = "z",
      method = "cr"
    ),
    error = function(e) NULL
  )

  if (is.null(resultat) || is.null(resultat$data)) {
    return(list(
      success = FALSE,
      message = "La préparation des données de mortalité avec `agesurv()` a échoué.",
      data = NULL
    ))
  }

  data_agesurv <- resultat$data

  if (!is.data.frame(data_agesurv) || nrow(data_agesurv) < 2) {
    return(list(
      success = FALSE,
      message = paste(
        "L'ajustement `agesurv()` a retourné un jeu de données trop incomplet",
        "(moins de 2 âges exploitables)."
      ),
      data = NULL
    ))
  }

  # Complétion des classes d'âge ====
  data_final <- tibble(age = seq(min(data_agesurv$age), max(data_agesurv$age))) |>
    left_join(data_agesurv, by = "age") |>
    mutate(number = replace_na(.data$number, 0L)) |>
    arrange(.data$age)

  list(
    success = TRUE,
    message = NULL,
    data = data_final
  )
}

#' Étendre artificiellement les données de fréquence d'âge avec des zéros
#'
#' Cette fonction ajoute des classes d'âge fictives avec un nombre de captures nul
#' (`number = 0`) au-delà de l'âge maximal observé, jusqu'à trois fois cet âge.
#' Cette étape permet d'améliorer l'ajustement de certains modèles de mortalité.
#'
#' La fonction retourne toujours une liste structurée contenant :
#' \itemize{
#'   \item `success` : indicateur logique de réussite
#'   \item `message` : message informatif si la préparation est impossible
#'   \item `data` : tableau étendu des fréquences d'âge, ou `NULL` si indisponible
#' }
#'
#' @param df_corrigee Un `data.frame` contenant les colonnes `age` (âge) et
#'   `number` (fréquence), généralement produit par `mortalite_prepare_corr()`.
#' @param age_max Un entier indiquant l'âge maximal observé, généralement issu
#'   de `mortalite_get_age_max()`.
#'
#' @return Une liste avec les éléments suivants :
#' \describe{
#'   \item{success}{Un booléen indiquant si la préparation a réussi.}
#'   \item{message}{Un message informatif si la préparation est impossible, sinon `NULL`.}
#'   \item{data}{Un `data.frame` combinant les âges observés avec les âges fictifs ajoutés, ou `NULL` si la préparation est impossible.}
#' }
#'
#' @importFrom dplyr arrange
#' @importFrom dplyr bind_rows
#' @importFrom tibble tibble
#'
#' @export
#'
#' @examples
#' df <- data.frame(age = 2:5, number = c(4, 3, 2, 1))
#' mortalite_prepare_extended(df, age_max = 5)
mortalite_prepare_extended <- function(df_corrigee, age_max) {
  # Validation de base ====
  if (is.null(df_corrigee) || !is.data.frame(df_corrigee)) {
    return(list(
      success = FALSE,
      message = "Les données corrigées sont invalides.",
      data = NULL
    ))
  }

  if (nrow(df_corrigee) == 0) {
    return(list(
      success = FALSE,
      message = "Aucune donnée corrigée n'est disponible pour étendre la structure d'âge.",
      data = NULL
    ))
  }

  if (!all(c("age", "number") %in% names(df_corrigee))) {
    return(list(
      success = FALSE,
      message = "Le tableau `df_corrigee` doit contenir les colonnes `age` et `number`.",
      data = NULL
    ))
  }

  if (is.null(age_max) || length(age_max) != 1 || is.na(age_max)) {
    return(list(
      success = FALSE,
      message = "L'âge maximal (`age_max`) est invalide ou manquant.",
      data = NULL
    ))
  }

  if (!is.numeric(age_max) || age_max < 0) {
    return(list(
      success = FALSE,
      message = "L'âge maximal (`age_max`) doit être un nombre supérieur ou égal à 0.",
      data = NULL
    ))
  }

  # Cas limite : aucun âge fictif à ajouter (ex: si age_max = 0) ====
  if (age_max * 3 <= age_max) {
    return(list(
      success = TRUE,
      message = NULL,
      data = df_corrigee |>
        arrange(.data$age)
    ))
  }

  # Génération des âges fictifs ====
  ages_fictifs <- tibble(
    age = (age_max + 1):(age_max * 3),
    number = 0
  )

  # Fusion et tri ====
  df_etendue <- bind_rows(df_corrigee, ages_fictifs) |>
    arrange(.data$age)

  list(
    success = TRUE,
    message = NULL,
    data = df_etendue
  )
}

#' Sélectionner le meilleur modèle de mortalité selon AICc et ajustement HNP
#'
#' Cette fonction identifie automatiquement le meilleur modèle parmi ceux
#' comparés (Poisson, NB1, NB2, CMP, GP), en priorisant les modèles ayant un
#' bon ajustement HNP (inférieur à 10 %). Si aucun modèle ne satisfait ce
#' critère, le modèle avec le plus faible AICc est sélectionné parmi les modèles
#' disponibles.
#'
#' La fonction retourne `NULL` si aucun modèle n'est sélectionnable.
#'
#' @param tablemodele Un `data.frame` généralement issu de
#'   `mortalite_compare_modele()$data`, contenant au minimum les colonnes :
#'   \describe{
#'     \item{methode}{Nom du modèle.}
#'     \item{aicc}{Critère d'information corrigé (numérique).}
#'     \item{ajustement_hnp}{Pourcentage d'ajustement HNP (numérique).}
#'     \item{convergence}{Booléen indiquant si le modèle est interprétable.}
#'   }
#'
#' @return Une chaîne de caractères correspondant au nom du meilleur modèle, ou
#'   `NULL` si aucun modèle n'est sélectionnable.
#'
#' @importFrom dplyr filter pull
#'
#' @export
#'
#' @examples
#' df <- data.frame(
#'   methode = c("poisson", "nb1", "nb2", "cmp", "gp"),
#'   aicc = c(112, 108, 109, 107, 106),
#'   ajustement_hnp = c(15, 12, 8, 6, 11),
#'   convergence = c(TRUE, TRUE, TRUE, TRUE, TRUE)
#' )
#' mortalite_select_best_modele(df)
mortalite_select_best_modele <- function(tablemodele) {
  # Validation de base ====
  if (is.null(tablemodele) || !is.data.frame(tablemodele) || nrow(tablemodele) == 0) {
    return(NULL)
  }

  required_cols <- c("methode", "aicc", "ajustement_hnp")

  if (!all(required_cols %in% names(tablemodele))) {
    return(NULL)
  }

  # Filtrer les modèles sélectionnables ====
  modeles_valides <- tablemodele |>
    filter(!is.na(.data$aicc))

  if ("convergence" %in% names(modeles_valides)) {
    modeles_valides <- modeles_valides |>
      filter(.data$convergence %in% TRUE)
  }

  if (nrow(modeles_valides) == 0) {
    return(NULL)
  }

  # Priorité aux modèles bien ajustés selon HNP ====
  modeles_bien_ajustes <- modeles_valides |>
    filter(!is.na(.data$ajustement_hnp), .data$ajustement_hnp < 10)

  if (nrow(modeles_bien_ajustes) > 0) {
    selection <- modeles_bien_ajustes |>
      filter(.data$aicc == min(.data$aicc, na.rm = TRUE)) |>
      pull("methode")
  } else {
    selection <- modeles_valides |>
      filter(.data$aicc == min(.data$aicc, na.rm = TRUE)) |>
      pull("methode")
  }

  if (length(selection) == 0 || is.na(selection[1])) {
    return(NULL)
  }

  selection[1]
}

test_hnp <- function(simuler,
                     ...,
                     n_init = 2,
                     n_suppl = 3,
                     seuil_inf = 10,
                     seuil_sup = 15) {

  set.seed(2023)

  # Première série de simulations
  res_hnp <- tryCatch(
    {
      simuler(..., n_iter = n_init)
    },
    error = function(e) NULL
  )

  if (is.null(res_hnp)) {
    return(list(
      ajustement_hnp = NA_real_,
      nb_iterations_hnp = NA_real_,
      graph_hnp = NULL
    ))
  }


  hnp_valeurs <- res_hnp$pct
  graph_hnp <- list(
      initial = res_hnp$hnp
      ) 

  ajustement_hnp <- round(mean(hnp_valeurs), 2)
  nb_iterations_hnp <- n_init


  # Si le résultat est limite, on ajoute des simulations
  if (!is.na(ajustement_hnp) &&
      ajustement_hnp >= seuil_inf &&
      ajustement_hnp < seuil_sup) {


    res_hnp_suppl <- tryCatch(
      {
        simuler(..., n_iter = n_suppl)
      },
      error = function(e) NULL
    )


    if (!is.null(res_hnp_suppl)) {

      hnp_valeurs <- c(
        hnp_valeurs,
        res_hnp_suppl$pct
      )

      graph_hnp$supplementaire <- res_hnp_suppl$hnp

      ajustement_hnp <- round(mean(hnp_valeurs), 2)
      nb_iterations_hnp <- n_init + n_suppl
    }
  }


  list(
    ajustement_hnp = ajustement_hnp,
    nb_iterations_hnp = nb_iterations_hnp,
    graph_hnp = graph_hnp
  )
}

#' Tester la sur-dispersion dans un modèle de Poisson (mortalité)
#'
#' Cette fonction applique un test de sur-dispersion (`dispersiontest()`)
#' à un modèle de Poisson ajusté sur les fréquences d'âge (`number ~ age`).
#' Elle retourne une liste structurée contenant :
#' \itemize{
#'   \item `success` : indicateur logique de réussite
#'   \item `message` : message d'interprétation ou d'erreur
#'   \item `dispersion` : valeur numérique estimée de dispersion, ou `NULL`
#'   \item `p_value` : p-value du test ou `NULL`
#'   \item `z` : la statistique z du test ou `NULL`
#'   \item `plot` : graphique des résidus de Pearson, ou `NULL`
#' }
#'
#' @param data Un `data.frame` contenant au minimum deux colonnes :
#'   \itemize{
#'   \item `age` : l'âge des poissons
#'   \item `number` : la fréquence d'individus observés pour chaque âge
#'   }
#'
#' @return Une liste avec les éléments suivants :
#' \describe{
#'   \item{success}{Un booléen indiquant si le test a pu être réalisé.}
#'   \item{message}{Un message d'interprétation si le test a réussi, ou un message informatif sinon.}
#'   \item{dispersion}{La valeur estimée de dispersion, ou `NULL` si le test n'a pas pu être réalisé.}
#'   \item{z}{La statistique z du test, ou `NULL` si le test n'a pas pu être réalisé.}
#'   \item{p_value}{La p-value du test de sur-dispersion, ou `NULL` si le test n'a pas pu être réalisé.}
#'   \item{plot}{Un objet `ggplot` des résidus de Pearson, ou `NULL` si le modèle n'a pas pu être ajusté.}
#' }
#'
#' @importFrom AER dispersiontest
#' @importFrom dplyr filter mutate
#' @importFrom ggplot2 aes geom_hline geom_point ggplot labs
#' @importFrom glue glue
#' @importFrom stats fitted glm poisson residuals
#' @importFrom tibble tibble
#'
#' @export
#'
#' @examples
#' set.seed(1)
#' df_test <- data.frame(
#'   age = 1:10,
#'   number = rpois(10, lambda = c(5, 10, 15, 20, 15, 10, 5, 4, 3, 2))
#' )
#'
#' res <- mortalite_test_surdispersion_poisson(df_test)
#' res$message
#' res$plot
mortalite_test_surdispersion_poisson <- function(data) {
  # Validation de base ====
  if (is.null(data) || !is.data.frame(data)) {
    return(list(
      success = FALSE,
      message = "Les données fournies sont invalides.",
      dispersion = NULL,
      plot = NULL
    ))
  }

  if (nrow(data) == 0) {
    return(list(
      success = FALSE,
      message = "Aucune donnée n'est disponible pour tester la sur-dispersion.",
      dispersion = NULL,
      plot = NULL
    ))
  }

  if (!all(c("age", "number") %in% names(data))) {
    return(list(
      success = FALSE,
      message = "Le tableau doit contenir les colonnes `age` et `number`.",
      dispersion = NULL,
      plot = NULL
    ))
  }

  # Nettoyage des données ====
  data_clean <- data |>
    filter(!is.na(.data$age), !is.na(.data$number)) |>
    mutate(age = as.integer(.data$age))

  if (nrow(data_clean) < 2) {
    return(list(
      success = FALSE,
      message = "Le test de sur-dispersion requiert au moins deux classes d'âge valides.",
      dispersion = NULL,
      plot = NULL
    ))
  }

  if (length(unique(data_clean$age)) < 2) {
    return(list(
      success = FALSE,
      message = "Le test de sur-dispersion requiert au moins deux âges distincts.",
      dispersion = NULL,
      plot = NULL
    ))
  }

  # Ajustement du modèle ====
  modele_poisson <- tryCatch(
    glm(number ~ age, family = poisson, data = data_clean),
    error = function(e) NULL
  )

  if (is.null(modele_poisson)) {
    return(list(
      success = FALSE,
      message = "Le modèle de Poisson n'a pas pu être ajusté pour tester la sur-dispersion.",
      dispersion = NULL,
      plot = NULL
    ))
  }

  # Test de sur-dispersion ====
  test_dispersion <- tryCatch(
    dispersiontest(modele_poisson, alternative = "greater"),
    error = function(e) NULL
  )

  if (is.null(test_dispersion) || is.null(test_dispersion$estimate)) {
    return(list(
      success = FALSE,
      message = "Le test de sur-dispersion n'a pas pu être calculé.",
      dispersion = NULL,
      plot = NULL
    ))
  }

   dispersion_value <- unname(test_dispersion$estimate["dispersion"]) |>
    round(2)

   z_value <- unname(test_dispersion$statistic) |>
     round(2)

   p_value <- test_dispersion$p.value |>
     round(3)

  if (is.na(dispersion_value)) {
    return(list(
      success = FALSE,
      message = "La valeur de dispersion n'a pas pu être estimée.",
      dispersion = NULL,
      plot = NULL
    ))
  }

  # Interprétation ====
   message <- if (p_value < 0.05) {
     glue(
       "Le test met en évidence une sur-dispersion statistiquement significative ",
       "(dispersion = {dispersion_value}, z = {z_value}, p = {p_value}). ",
       "Des modèles alternatifs comme NB1, NB2, CMP ou GP devraiet être envisagés."
     )
   } else {
     glue(
       "Le test ne met pas en évidence de sur-dispersion statistiquement significative ",
       "(dispersion = {dispersion_value}, z = {z_value}, p = {p_value}). "
     )
   }

  # Graphique des résidus ====
#  data_plot <- tibble(
#    fitted = fitted(modele_poisson),
#    residuals = residuals(modele_poisson, type = "pearson")
#  )

#  plot <- ggplot(data_plot, aes(x = fitted, y = residuals)) +
#    geom_point(color = "#0072B2", size = 2) +
#    geom_hline(yintercept = 0, linetype = "dashed") +
#    labs(
#      x = "Valeurs ajustées (Poisson)",
#      y = "Résidus de Pearson",
#      title = "Résidus vs valeurs ajustées (modèle Poisson)"
#    ) +
#    theme_aquapop()

  # Sortie ====
  list(
    success = TRUE,
    message = as.character(message),
    dispersion = dispersion_value,
    z = unname(test_dispersion$statistic),
    p_value = test_dispersion$p.value,
    plot = plot
  )
}

